    const createdAt = this.now();
    const myKey = this.requireMyIdentityKey("sendInvoice requires the wallet to provide an identity key");
    const thread = {
      threadId,
      counterparty: to,
      myRole: "maker",
      theirRole: "taker",
      createdAt,
      updatedAt: createdAt,
      state: "new",
      stateLog: [],
      processedMessageIds: [],
      protocolLog: [],
      identity: {
        certsSent: [],
        certsReceived: [],
        requestSent: false,
        responseSent: false,
        acknowledgmentSent: false,
        acknowledgmentReceived: false
      },
      flags: {
        hasIdentified: false,
        hasInvoiced: false,
        hasPaid: false,
        hasReceipted: false,
        error: false
      }
    };
