async function createSocialPost2(args, wallet3) {
  try {
    const { content, contentType, app, additionalMapData } = args;
    const paymentKey = wallet3.getPaymentKey();
    if (!paymentKey) {
      return {
        success: false,
        error: "Payment key not available in wallet"
      };
    }
    const address = paymentKey.toAddress();
    const fileExtension = contentType === "text/markdown" ? "md" : "txt";
    const fileName = `post.${fileExtension}`;
    const bData = [
      toArray15(B_PREFIX, "utf8"),
      toArray15(content, "utf8"),
      toArray15(contentType, "utf8"),
      toArray15("utf-8", "utf8"),
      toArray15(fileName, "utf8")
    ];
    const mapData = [
      toArray15(MAP_PREFIX2, "utf8"),
      toArray15("SET", "utf8"),
      toArray15("app", "utf8"),
      toArray15(app, "utf8"),
      toArray15("type", "utf8"),
      toArray15("post", "utf8")
    ];
    if (additionalMapData) {
      const parsedMapData = JSON.parse(additionalMapData);
      for (const [key, value2] of Object.entries(parsedMapData)) {
        mapData.push(toArray15(key, "utf8"), toArray15(value2, "utf8"));
      }
    }
    const pipeData = toArray15("|", "utf8");
    const dataToSign = [...bData, pipeData, ...mapData];
    const { signedData } = await signOpReturnWithAIP(dataToSign, paymentKey, address);
    const script3 = buildOpReturnScript(signedData);
    const { paymentUtxos } = await wallet3.getUtxos();
    return await buildAndSendTransaction({
      outputs: [{ script: script3, satoshis: 0 }],
      utxos: paymentUtxos,
      changeAddress: address,
      paymentKey
    });
  } catch (error52) {
    console.error("Error creating social post:", formatError2(error52));
    return {
      success: false,
      error: formatError2(error52)
    };
  }
}
