// tools/bsocial/readPosts.ts
async function readSocialPosts(args) {
  try {
    const { bapId, txid, limit, page, feed } = args;
    if (txid) {
      const response2 = await fetch(`${BMAP_URL}/post/${txid}`, {
        method: "GET",
        headers: {
          "Content-Type": "application/json"
        }
      });
      if (!response2.ok) {
        const errorText = await response2.text();
        return {
          success: false,
          error: `BMAP API request failed: ${response2.status} ${errorText}`
        };
      }
      const data2 = await response2.json();
      if (data2.status !== "success") {
        return {
          success: false,
          error: data2.error || "Unknown API error"
        };
      }
      return {
        success: true,
        posts: [data2.data.post],
        signers: data2.data.signers,
        meta: [data2.data.meta]
      };
    }
    const params = new URLSearchParams;
    if (bapId)
      params.append("bapId", bapId);
    params.append("limit", limit.toString());
    params.append("page", page.toString());
    if (feed)
      params.append("feed", "true");
    const response = await fetch(`${BMAP_URL}/posts?${params}`, {
      method: "GET",
      headers: {
        "Content-Type": "application/json"
      }
    });
    if (!response.ok) {
      const errorText = await response.text();
      return {
        success: false,
        error: `BMAP API request failed: ${response.status} ${errorText}`
      };
    }
    const data = await response.json();
    if (data.status !== "success") {
      return {
        success: false,
        error: data.error || "Unknown API error"
      };
    }
    return {
      success: true,
      posts: data.data.results,
      signers: data.data.signers,
      meta: data.data.meta,
      pagination: {
        page: data.data.page,
        limit: data.data.limit,
        count: data.data.count
      }
    };
  } catch (error52) {
    const errorMessage = error52 instanceof Error ? error52.message : String(error52);
    console.error("Error reading social posts:", errorMessage);
    return {
      success: false,
      error: errorMessage
    };
  }
}
function formatPost(post, index, signer, meta3) {
  const lines = [
    `Post ${index + 1}:`,
    `  TX ID: ${post.tx.h}`,
    `  Content: ${post.B[0]?.content || "[No Content]"}`,
    `  Content Type: ${post.B[0]?.["content-type"] || "text/plain"}`,
    `  Timestamp: ${new Date(post.timestamp * 1000).toISOString()}`
  ];
  if (signer) {
    lines.push(`  Author: ${signer.displayName || signer.idKey}`);
    if (signer.paymail) {
      lines.push(`  Paymail: ${signer.paymail}`);
    }
  }
  const mapData = post.MAP.find((m5) => m5.type === "post");
  if (mapData?.app) {
    lines.push(`  App: ${mapData.app}`);
  }
  if (meta3) {
    if (meta3.likes > 0) {
      lines.push(`  Likes: ${meta3.likes}`);
    }
    if (meta3.replies > 0) {
      lines.push(`  Replies: ${meta3.replies}`);
    }
    if (meta3.reactions.length > 0) {
      const reactions = meta3.reactions.map((r4) => `${r4.emoji}(${r4.count})`).join(" ");
      lines.push(`  Reactions: ${reactions}`);
    }
  }
  return lines.join(`
`);
}
