function registerCancelListingTool(server, ctx) {
  server.tool("wallet_cancelListing", "Cancel an ordinal marketplace listing", { ...cancelListingArgsSchema.shape }, async ({ id }) => {
    if (!ctx) {
      return {
        content: [
          {
            type: "text",
            text: "Wallet not initialized. Please configure a wallet before cancelling."
          }
        ],
        isError: true
      };
    }
    try {
      assertBroadcastAllowed("wallet_cancelListing");
      const result2 = await cancelOrdinalListing.execute(ctx, { id });
      if (result2.error) {
        return {
          content: [{ type: "text", text: result2.error }],
          isError: true
        };
      }
      return {
        content: [
          {
            type: "text",
            text: JSON.stringify(result2, (_5, v7) => typeof v7 === "bigint" ? v7.toString() : v7, 2)
          }
        ]
      };
    } catch (err) {
      return {
        content: [
          {
            type: "text",
            text: err instanceof Error ? err.message : String(err)
          }
        ],
        isError: true
      };
    }
  });
}
