function registerCreateOrdinalsTool(server, ctx) {
  server.tool("wallet_createOrdinals", "Creates and inscribes ordinals (NFTs) on the Bitcoin SV blockchain. This tool lets you mint new digital artifacts by encoding data directly into the blockchain. Supports various content types including images, text, JSON, and HTML. The tool handles transaction creation, fee calculation, and broadcasting.", { ...createOrdinalsArgsSchema.shape }, async ({
    dataB64,
    contentType,
    destinationAddress,
    metadata,
    signWithBAP
  }) => {
    if (!ctx) {
      return {
        content: [
          {
            type: "text",
            text: "Wallet not initialized. Please configure a wallet before creating ordinals."
          }
        ],
        isError: true
      };
    }
    try {
      assertBroadcastAllowed("wallet_createOrdinals");
      const result2 = await inscribe.execute(ctx, {
        base64Content: dataB64,
        contentType,
        map: metadata,
        signWithBAP,
        ...destinationAddress && {
          destination: { address: destinationAddress }
        }
      });
      if (result2.error) {
        return {
          content: [{ type: "text", text: result2.error }],
          isError: true
        };
      }
      return {
        content: [
          {
            type: "text",
            text: JSON.stringify({
              txid: result2.txid,
              contentHash: result2.contentHash,
              contentType
            })
          }
        ]
      };
    } catch (err) {
      return {
        content: [
          {
            type: "text",
            text: err instanceof Error ? err.message : String(err)
          }
        ],
        isError: true
      };
    }
  });
}
